mapper.select:
WITH RECURSIVE T ( ID, field,field_name,field_type, parent_id, PATH ) AS (
    SELECT ID,field,field_name,field_type,PARENT_ID,ID::text AS PATH FROM cfg_logistics_cost_import_field
    WHERE parent_id = '0' and business_type = #{businessType}
    UNION ALL
    SELECT st.ID,st.field,st.field_name,st.field_type,st.PARENT_ID,T.PATH ||','|| st.ID
    FROM cfg_logistics_cost_import_field st JOIN T ON st.PARENT_ID = T.ID
)
SELECT ID,field,field_name,field_type,PARENT_ID,PATH FROM T ORDER BY 	PATH;
